function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 2 || arr.length > 30000) return 'arr needs 2 to 3 * 10^4 values.';
  if (arr.length % 2 !== 0) return 'arr must have an even length.';
  if (arr.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value is a whole number from -10^5 to 10^5.';
  return null;
}

