function canReorderDoubled(arr) {
  const count = new Map();
  for (const value of arr) {
    count.set(value, (count.get(value) || 0) + 1);
  }

  const sorted = [...arr].sort((a, b) => Math.abs(a) - Math.abs(b));

  for (const value of sorted) {
    if (count.get(value) === 0) {
      continue;
    }
    count.set(value, count.get(value) - 1);
    const partner = 2 * value;
    const partnerCount = count.get(partner) || 0;
    if (partnerCount === 0) {
      return false;
    }
    count.set(partner, partnerCount - 1);
  }
  return true;
}

