function canReorderDoubled(arr) {
  // Backtracking: pair the first unused element with every possible partner.
  const used = new Array(arr.length).fill(false);
  const solve = () => {
    const i = used.indexOf(false);
    if (i === -1) return true;
    used[i] = true;
    for (let j = 0; j < arr.length; j++) {
      if (used[j]) continue;
      if (arr[j] === 2 * arr[i] || arr[i] === 2 * arr[j]) {
        used[j] = true;
        if (solve()) return true;
        used[j] = false;
      }
    }
    used[i] = false;
    return false;
  };
  return solve();
}

