function generate(rand, size) {
  const int = (k) => Math.floor(rand() * k);
  const large = size === 'large';
  const pairs = large ? 1000 : 1 + int(4);
  const limit = large ? (rand() < 0.5 ? 40 : 50000) : 1 + int(6);
  const arr = [];
  for (let k = 0; k < pairs; k++) {
    const x = int(2 * limit + 1) - limit;
    arr.push(x, 2 * x);
  }
  for (let k = arr.length - 1; k > 0; k--) {
    const j = int(k + 1);
    [arr[k], arr[j]] = [arr[j], arr[k]];
  }
  // Half of the inputs get one element changed, which usually breaks the pairing.
  if (rand() < 0.5) {
    const at = int(arr.length);
    if (!large && rand() < 0.4) arr[at] = int(13) - 6;
    else arr[at] = arr[at] < 100000 ? arr[at] + 1 : arr[at] - 1;
  }
  return [arr];
}
